import React, { useEffect, useState } from "react";
import * as Yup from "yup";
import {
  ModalContent,
  ModalHeader,
  ModalBody,
  ModalFooter,
  Button,
  Input,
} from "@heroui/react";
import {
  CustomDatePicker,
  CustomForm,
  CustomFormItem,
  CustomInput,
  CustomSelectAsyncSelect,
  CustomSelectReactSelect,
  FileUploader,
  Loading,
} from "../../components";
import { useFormik } from "formik";
import { ToastContainer, toast } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";

import { DatePicker, Modal, Space } from "antd";
import dayjs from "dayjs";
import "dayjs/locale/en-gb";
import { useDispatch } from "react-redux";
import { addEntity, updateEntity } from "../../redux/users/entities/actions";
import { getLoggedInUser } from "../../helpers/authUtils";
import entityTypes from "../../data/entityTypes";
import entityOwnerships from "../../data/entityOwnerships";
import useApi from "../../hooks/useApi";
import countiesApi from "../../api/countiesApi";
import { useStateContext } from "../../contexts/ContextProvider";

export default function EntitiesFormModalFormModal({
  openEditModal,
  setopenEditModal,
  entity,
  modalTitle = "Add new wholesale inventory",
  updated,
  setUpdated,
}) {
  const dispatch = useDispatch();
  const [user, setUser] = useState();
  const [errors, setErrors] = useState();
  const {currentColor} =useStateContext()

  //Retrieve counties
  const [counties, setCounties] = useState([]);
  const countiesActionsApi = useApi(countiesApi.countiesAction);
  const getCounties = async () => {
    await countiesActionsApi.request({
      action: "GetCounties",
    });
  };

  useEffect(() => {
    getCounties();
  }, []);

  useEffect(() => {
    if (countiesActionsApi.data && countiesActionsApi.data.length) {
      setCounties(
        countiesActionsApi.data.map((i) => ({ label: i.title, value: i.id }))
      );
    }
    console.log("counties", counties);
  }, [countiesActionsApi.data]);

  const [isKenyan, setisKenyan] = useState(false);

  useEffect(() => {
    console.log("userrr", user);
    if (user) {
      setisKenyan(user.country_title === "KENYA");
    }

    console.log("User", user);
  }, [user]);

  useEffect(() => {
    setUser(getLoggedInUser());
  }, []);

  useEffect(() => {
    if (errors && errors.length) {
      errors.map((x) => {
        toast.error(x);
      });
    }
  }, [errors]);
  const formik = useFormik({
    initialValues: {
      title: entity ? entity.title : "",
      description: entity ? entity.description : "",
      county: entity
        ? { label: entity.county_title, value: entity.county }
        : { label: "Select county", value: "" },
      entity_type: entity
        ? { label: entity.entity_type, value: entity.entity_type }
        : "",
      entity_ownership: entity
        ? { label: entity.entity_ownership, value: entity.entity_ownership }
        : "",
      town: entity ? entity.town : "",
      road: entity ? entity.road : "",
      building: entity ? entity.building : "",
      licences: [],
    },

    validationSchema: Yup.object({
      licences: Yup.array()
        .label("Business licences")
        .min(1, "Upload at least one business licence/certificate")
        .max(5, "Not more than 5 images permmited"),
      title: Yup.string()
        .min(3, "Must be 15 characters or more")
        .required("Title is required"),
      entity_type: Yup.object().required("Entity type is required"),
      road: Yup.string().required("Road is required"),
      building: Yup.string().required("Town is required"),
      town: Yup.string().required("Town is required"),
      entity_ownership: Yup.object().required(
        "Entity ownership type is required"
      ),
      county: Yup.object().required("County is required"),
      description: Yup.string()
        .min(50, "Briefly describe your business")
        .required("Description is required"),
    }),
    onSubmit: (values, { resetForm }) => {
      //Dispatch action

      console.log("VALZ", values);
      let arr = [];
      if (values.categories && values.categories.length) {
        values.categories.map((x) => {
          arr.push(x.value);
        });
      }

      let data = new FormData();

      data.append("title", values.title);
      data.append("town", values.town);
      data.append("building", values.building);
      data.append("road", values.road);
      data.append("description", values.description);
      data.append("county", values.county.value);
      data.append("country", user.country_id);
      data.append("entity_ownership", values.entity_ownership.value);
      data.append("entity_type", values.entity_type.value);
      values.licences.map((x) => {
        data.append("licences", x);
      });

      if (entity) {
        dispatch(updateEntity(data));
      } else {
        dispatch(addEntity(data));
      }

      resetForm();

      // if (item) {

      //     handleEntitiesAction({
      //         "action": "UpdateEntity",
      //         "entity": entity.id,
      //         "entity_details": {
      //             "title": values.title,
      //             "country": user.country_id,
      //             "county": values.county.value,
      //             "categories": arr,
      //             "town": values.town,
      //             "road": values.road,
      //             "building": values.building,
      //         }
      //     })
      // } else {
      //     handleEntitiesAction({
      //         "action": "CreateLocalEntity",
      //         "entity_details": {
      //             "title": values.title,
      //             "entity_type": values.entity_type.value,
      //             "entity_ownership": values.entity_ownership.value,
      //             "entity_code": values.entity_code,
      //             "country": user.country_id,
      //             "county": values.county.value,
      //             "categories": arr,
      //             "town": values.town,
      //             "road": values.road,
      //             "building": values.building,
      //         }
      //     })
      // }

      // resetForm();
    },
  });

  //Load products

  const [products, setProducts] = useState();

  useEffect(() => {
    console.log("formik", formik.errors);
  }, [formik]);

  const handleOk = () => {
    setopenEditModal(false);
  };
  const handleCancel = () => {
    setopenEditModal(false);
  };

  const handleRemoveSelectedImage = (file) => {
    console.log("file", file);
    // formik.values.licences.filter((x) => x.preview !== file.preview);

    formik.setFieldValue(
      "licences",
      formik.values.licences.filter((x) => x.preview !== file.preview)
    );
  };

  return (
    <div className="w-full">
      <Modal
        width={800}
        className="w-full text-center"
        title={entity ? `EDIT ${entity.title}` : modalTitle}
        open={openEditModal}
        onOk={handleOk}
        onCancel={handleCancel}
        closeIcon={true}
        closable={false}
        cancelButtonProps={{ style: { display: "none" } }}
        okButtonProps={{ style: { display: "none" } }}
      >
        <ToastContainer theme="colored" position="bottom-center" />
        <CustomForm
          layout="vertical"
          handleFinish={formik.handleSubmit}
          className=" flex flex-col justify-center items-center w-full"
        >
          <div className="w-full grid grid-cols-2 mt-5 gap-1 ">
            <CustomFormItem
              touched={formik.touched.title}
              error={formik.errors.title}
            >
              <CustomInput
                required={true}
                label="Enter entity title"
                id="title"
                name="title"
                onChange={formik.handleChange}
                placeholder="Enter entity title"
                size="large"
                type="text"
                value={formik.values.title}
              />
            </CustomFormItem>

            {isKenyan ? (
              <CustomFormItem
                touched={formik.touched.town}
                error={formik.errors.town}
              >
                <CustomInput
                  required={true}
                  label="Enter town located"
                  id="town"
                  name="town"
                  onChange={formik.handleChange}
                  placeholder="Enter town located"
                  size="large"
                  type="text"
                  value={formik.values.town}
                />
              </CustomFormItem>
            ) : (
              <div></div>
            )}

            {isKenyan ? (
              <CustomFormItem
                touched={formik.touched.road}
                error={formik.errors.road}
              >
                <CustomInput
                  required={true}
                  label="Enter road located"
                  id="road"
                  name="road"
                  onChange={formik.handleChange}
                  placeholder="Enter road located"
                  size="large"
                  type="text"
                  value={formik.values.road}
                />
              </CustomFormItem>
            ) : (
              <div></div>
            )}

            {isKenyan ? (
              <CustomFormItem
                touched={formik.touched.building}
                error={formik.errors.building}
              >
                <CustomInput
                  label="Enter building located"
                  id="building"
                  name="building"
                  onChange={formik.handleChange}
                  placeholder="Enter building located"
                  size="large"
                  type="text"
                  value={formik.values.building}
                />
              </CustomFormItem>
            ) : (
              <div></div>
            )}

            {isKenyan ? (
              <CustomFormItem
                touched={formik.touched.entity_ownership}
                error={formik.errors.entity_ownership}
              >
                <CustomSelectReactSelect
                  className="text-start"
                  name="entity_ownership"
                  id="entity_ownership"
                  label="Select entity ownership type"
                  size="large"
                  onChange={(value) =>
                    formik.setFieldValue("entity_ownership", value)
                  }
                  value={formik.values.product}
                  placeholder="Select entity ownership type"
                  options={counties}
                />
              </CustomFormItem>
            ) : (
              <div></div>
            )}

            <CustomFormItem
              touched={formik.touched.entity_type}
              error={formik.errors.entity_type}
            >
              <CustomSelectReactSelect
                className="text-start"
                name="entity_type"
                id="entity_type"
                label="Select entity type "
                size="large"
                onChange={(value) => formik.setFieldValue("entity_type", value)}
                value={formik.values.product}
                placeholder="Select entity type"
                options={entityTypes}
              />
            </CustomFormItem>

            <CustomFormItem
              touched={formik.touched.entity_ownership}
              error={formik.errors.entity_ownership}
            >
              <CustomSelectReactSelect
                className="text-start"
                name="entity_ownership"
                id="entity_ownership"
                label="Select entity ownership type"
                size="large"
                onChange={(value) =>
                  formik.setFieldValue("entity_ownership", value)
                }
                value={formik.values.product}
                placeholder="Select entity ownership type"
                options={entityOwnerships}
              />
            </CustomFormItem>
          </div>
          <div className="bg-white">
            <FileUploader
              placeholder="Upload business legal licences e.g. certificate of registration, business name certificate, current council business licence, e.t.c."
              formik={formik}
              name="licences"
              types=".png,.jpg,.jpeg"
              value={formik.values.licences}
              accept={{
                "image/png": [".png"],
                "image/jpeg": [".jpeg"],
              }}
            />
            {formik.errors.licences ? (
              <p className="text-red-500 text-xs">{formik.errors.licences}</p>
            ) : null}
            {formik.values.licences && formik.values.licences.length > 0 && (
              <div className="shadow-md rounded my-5 bg-zinc-100 p-5">
                <h2 className="text-center font-bold mb-5">
                  Documents selected for upload
                </h2>
                <div className="container flex flex-wrap mx-auto text-black max-h-40">
                  <div className="grid grid-cols-4 gap-2 sm:grid-cols-4 gap-3">
                    {formik.values.licences?.map((file) => (
                      <div
                        className="md:shrink-0 rounded bg-white items-center justify-center "
                        key={file.preview}
                      >
                        <button
                          onClick={() => handleRemoveSelectedImage(file)}
                          className="flex bg-white  absolute text-red-500 border-red-500 border border-white hover:text-red-800  font-bold text-4xl"
                        >
                          x
                        </button>
                        <img
                          style={{ height: 150, width: 150 }}
                          className="h-10 w-10 object-cover md:h-full md:w-48 shadow-md"
                          src={file.preview}
                          alt=""
                        />
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            )}
          </div>
          <div className="w-full items-center mt-2">
            <Button
              style={{ background: currentColor }}
              className="w-36 rounded-md"
              color="primary"
              type="submit"
            >
              Submit
            </Button>
          </div>
        </CustomForm>
      </Modal>
    </div>
  );
}
