import React, { useEffect, useState } from 'react'
import EntitiesTable from './EntitiesTable'

import useApi from '../../hooks/useApi'
import { useNavigate } from 'react-router-dom';
import EntitiesFormModalAdmin from './EntitiesFormModalAdmin';
import entitiesApi from '../../api/entitiesApi';
import { getLoggedInUser, logOutUser } from '../../helpers/authUtils';
import EntitiesFormModal from './EntitiesFormModal';
import { Loading, YesNoModal } from '../../components';
import { useSelector } from 'react-redux';
import { ToastContainer, toast } from "react-toastify";

const columns = [

    { name: "Title", uid: "title" },
    { name: "Type", uid: "entity_type" },
    { name: "Country", uid: "country_title" },
    { name: "County", uid: "county_title" },
    { name: "City", uid: "town" },
    { name: "Road", uid: "road" },
    { name: "Building", uid: "building" },
    { name: "Actions", uid: "actions" },
];


function EntitiesList() {
    const [openEntityFormModalAdmin, setopenEntityFormModalAdmin] = useState(false)
    const [openEntityFormModal, setopenEntityFormModal] = useState(false)
    const navigate = useNavigate()
    const [entity, setEntity] = useState()
    const [entities, setEntities] = useState([])
    const [data, setdata] = useState([])
    const [updated, setUpdated] = useState(false)
    const [modalTitle, setmodalTitle] = useState("")
    const entitiesActionsApi = useApi(entitiesApi.entitiesAction)
    const [showYesNoModal, setshowYesNoModal] = useState(false)
    const [selectedEntity, setselectedEntity] = useState()
    const [errors, seterrors] = useState([])



    

    const [user, setUser] = useState()

    //Redux 
    const created = useSelector((state) => state.Entities.created);



    useEffect(() => {
        setUser(getLoggedInUser())

    }, [])

    const getEntities = async (action) => {
        setEntities([])
        await entitiesActionsApi.request({
            "action": action

        })
    }



    useEffect(() => {
      getEntities("GetAllEntities");
    }, []);

    const handleEditAction = (item) => {
      console.log("Selected item", item);
      setselectedEntity(item);

      toast.success(`SWITCHING YOU TO ${item.title}`);

      if (user && user.is_staff === "true") {
        setopenEntityFormModalAdmin(true);
        setUpdated(false);

        setEntity(item);
        setmodalTitle(`${item.title}`);
      } else {
        setshowYesNoModal(true);
      }
    };

    const handleAddAction = () => {
      if (user && user.is_staff === "true") {
        setopenEntityFormModalAdmin(true);
      } else {
        setopenEntityFormModal(true);
      }
      setUpdated(false);

      setmodalTitle("Add new entity");
      setEntity(null);
    };
    const handleDetailsAction = (item) => {
      navigate(`/entities/details/${item.id}`, {
        state: {
          item: item,
        },
      });
    };
    const handleDeleteAction = (item) => {
      navigate(`/entities/delete/${item.id}`);
    };

    useEffect(() => {
      if (entitiesActionsApi.data && entitiesActionsApi.data.length) {
        setEntities(entitiesActionsApi.data);
      }

      console.log("entitiesActionsApi.data", entitiesActionsApi.data);
    }, [entitiesActionsApi.data]);

    // useEffect(() => {
    //     getEntities()
    // }, [openEntityFormModal])

    //Filtering data
    useEffect(() => {
      setdata(entities);
    }, [entities]);

    const handleFilter = (e) => {
      console.log("eeeee", e);
      const search_param = e;

      if (search_param && search_param !== "") {
        setdata(
          entities.filter((x) => x.title.toLowerCase().includes(search_param))
        );
      } else {
        setdata(entitiesActionsApi.data);
      }
    };

    const handleSwitchEntity=async()=>{
        const result = await entitiesActionsApi.request({
            "action":"SwitchToEntity",
            "entity":selectedEntity.id
          
        }) 

        if(result.ok){
            toast.success(entitiesActionsApi.data.response_message)
            logOutUser()
            navigate("/login")
            
        }else{
          
            // toast.error("Failure")
            if(entitiesActionsApi.data.errors && entitiesActionsApi.data.errors.length){
                seterrors(entitiesActionsApi.data.errors)
                
            }
        }
    }

    useEffect(() => {
        if (errors && errors.length) {
            errors.map((x) => {
                toast.error(x);
            });
        }
    }, [errors]);

    return (
        <div>

        <ToastContainer position="bottom-center" theme="colored" />
        <YesNoModal showModal={showYesNoModal} setShowModal={setshowYesNoModal} title="Switch Entity" content="You are about to switch to selected entity. You will have to log in again after this action." yesAction={()=>handleSwitchEntity()} noAction={()=>setshowYesNoModal(false)}/>
            {openEntityFormModal && <EntitiesFormModal openEditModal={openEntityFormModal} setopenEditModal={setopenEntityFormModal} item={entity} updated={updated} setUpdated={setUpdated} modalTitle={modalTitle} />}
            {openEntityFormModalAdmin && <EntitiesFormModalAdmin openEditModal={openEntityFormModalAdmin} setopenEditModal={setopenEntityFormModalAdmin} item={entity} updated={updated} setUpdated={setUpdated} modalTitle={modalTitle} />}
            {entitiesActionsApi.loading ? <Loading loading={entitiesActionsApi.loading} /> : <EntitiesTable data={data} columns={columns}
                editAction={handleEditAction} detailsAction={handleDetailsAction} deleteAction={handleDeleteAction} addAction={handleAddAction} handleFilter={handleFilter} />}
        </div>
    )
}

export default EntitiesList